class Component
{
public:
    bool exists = false;
}

// exists = whether the entity actually contains the derived component
// default to false so default constructed components are not considered part of the Entity

class Transform : public Component
{
public:
    Vec2 pos = {0,0};
    Vec2 velocity = {0,0};
    Transform() {}
    Transform(const Vec2 &p, const Vec2 &v) : pos(p), velocity(v) {}
}

class Entity
{
    std::tuple<C1, C2, C3, C4> components;
    bool alive = true;
    std::string tag = "default";
    size_t id = 0;
public:
    Entity() {}
    void add<T>(args);
    T& get<T>();
    size_t id() const;
    bool is_alive() const;
    void destroy();
    const std::string& tag() const;
}

void doSomething(std::vector<Entity> &entities) {
    for (auto& e: entities) {
        e.transform.pos += e.transform.velocity;
        e.shape.shape.setPosition(e.transform.pos);
        window.draw(e.shape.shape);
    }
}

void movement(std::vector<Entity> &entities) {
    for (auto& e: entities) {
        e.transform.pos += e.transform.velocity;
        e.shape.shape.setPosition(e.transform.pos);
        window.draw(e.shape.shape);
    }
}

void lifespan() {
    for (auto& e: entityManager.getEntities()) {
	if (!e->has<Lifespan>()) { continue; };
	e.get<Lifespan>().remainingLifespan--;
	if (e.get<Lifespan>().remainingLifespan <= 0) {
	    e.destroy();
	}
    }
}

void render() {
    for (auto& e: entityManager.getEntities()) {
	if (e->has<Shape>() && e->has<Transform>()) {
	    e.shape.shape.setPosition(e.transform.pos);
	    window.draw(e.shape.shape);
	}
    }
}

class EntityManager
{
    EntityVec entities; // all entities
    EntityMap entityMap; // all entities by tag
    size_t totalEntities = 0;
public:
    EntityManager()
    std::shared_ptr<Entity> addEntity(const std::string& tag); // add a new entity of a specific type
    EntityVec& getEntities(); // get the full list of entities
    EntityVec& getEntities(const std::string& tag); // get list of entities by tag
}

void spawnEnemy
{
    auto e = entityManager.addEntity("enemy");
    e->add<Transform>(args);
    e->add<Shape>(args);
}
